css:
.letter-head, .letter-head-footer { display: none !important; }


.print-format, .print-format div, .print-format p, .print-format td, .print-format th, .print-format span, .print-format small {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif;
}

.print-format .lat, .print-format .lat span,
.print-format table.afm-items td:nth-child(1), .print-format table.afm-items td:nth-child(n+4),
.print-format table.afm-tot td:nth-child(2) {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif;
}
.print-format { color: #171717; -webkit-print-color-adjust: exact; }
.print-format .afm-k { color: #5f5f5f; }
.print-format .section-break small p { color: #5f5f5f; }

.print-format p.lat, .print-format p.afm-k { margin: 0 !important; }
.print-format p.afm-k + br { display: none; }


.print-format .print-heading.afm-title { border: 0; margin: 0; padding: 0; text-align: center; }
.print-format .print-heading.afm-title h2 {
  font-size: 13pt; line-height: 20px; font-weight: bold; color: #171717;
  margin: 8px 0 0 0; padding: 0 0 4px 0; border-bottom: 1.2pt solid #00844e;
}


.print-format table.afm-items tr { page-break-inside: avoid; }
.print-format table.afm-items { border: 0.75pt solid #d0d0d0; border-bottom: 0.75pt solid #d0d0d0; }
.print-format table.afm-items th {
  background: #f4f4f4 !important; color: #171717 !important; font-weight: bold;
  border: 0.75pt solid #d0d0d0 !important; border-top: 1.2pt solid #00844e !important;
  vertical-align: bottom !important;
}
.print-format table.afm-items td { border: 0.75pt solid #d0d0d0 !important; background: #ffffff !important; }
.print-format table.afm-items th:nth-child(n+4), .print-format table.afm-items td:nth-child(n+4) { text-align: right !important; }
.print-format table.afm-items td:nth-child(n+4) { white-space: nowrap; }


.print-format .page-break > .section-break:nth-last-child(2), .print-format table.afm-tot { page-break-inside: avoid; }


.print-format table.afm-tot { border: 0.75pt solid #d0d0d0; margin-bottom: 8px; }
.print-format table.afm-tot td { border: 0.75pt solid #d0d0d0 !important; background: #ffffff !important; }
.print-format table.afm-tot td:nth-child(2) { text-align: right !important; white-space: nowrap; font-weight: bold; vertical-align: middle !important; }
.print-format table.afm-tot tr.afm-grand td { background: #00844e !important; color: #ffffff !important; font-weight: bold; border-color: #00844e !important; }


.print-format .afm, .print-format .afm td, .print-format .afm th, .print-format .afm div, .print-format .afm span {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm .num, .print-format .afm .ltr, .print-format .afm .num span, .print-format .afm .ltr2 {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm { color: #171717; font-size: 8.5pt; line-height: 14px; direction: rtl; text-align: right; -webkit-print-color-adjust: exact; }
.afm * { box-sizing: border-box; }
.afm table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; margin: 0; }
.afm .num { white-space: nowrap; direction: ltr; unicode-bidi: embed; text-align: right; }
.afm .ctr { text-align: center !important; }
.afm .ltr { direction: ltr; unicode-bidi: embed; }
.afm-hdr .logo img { height: 48px; width: auto; display: block; }
.print-format .afm-hdr td { padding: 0 !important; vertical-align: middle !important; border: 0; }
.afm-hdr .ids td { font-size: 8.5pt; line-height: 14px; white-space: nowrap; vertical-align: baseline !important; }
.afm-hdr .ids .k { font-size: 7pt; color: #5f5f5f; }
.afm-hdr .ids .k.ltr { font-size: 6pt; }
.afm-hdr .rule td { height: 8px; }
.afm-hdr .rule .thin { border-bottom: 0.75pt solid #00844e; }
.afm-hdr .rule .thick { border-bottom: 2.4pt solid #00844e; }
.print-format .afm-ftr td { border-top: 0.75pt solid #00844e; padding: 4px 0 0 0 !important; font-size: 7pt; line-height: 12px; color: #5f5f5f; vertical-align: top !important; }
.afm-ftr .ltr { white-space: nowrap; }
.afm-ftr .co { white-space: nowrap; }
.afm-ftr .ltr2 { direction: ltr; text-align: right; white-space: nowrap; padding: 0 4px 0 0; }
.afm-ftr .pg { white-space: nowrap; color: #171717; }


.print-format table.afm-items .ql-editor { overflow: visible !important; height: auto !important; padding: 0 !important; }
.print-format table.afm-items .ql-editor p { margin: 0 !important; }

